{"cells":[{"cell_type":"code","source":"import os\nfrom azure.cosmos.aio import CosmosClient\nfrom azure.cosmos import PartitionKey\nfrom dotenv import load_dotenv\nimport asyncio\n\nload_dotenv()\n\n# Cosmos DB configuration\nCOSMOS_DB_ENDPOINT = os.getenv(\"COSMOS_DB_ENDPOINT\")\nCOSMOS_DB_KEY = os.getenv(\"COSMOS_DB_KEY\")\nDATABASE_NAME = \"ChatDB\"\nCONTAINER_NAME = \"Conversations\"\n\n\nasync def get_cosmos_client():\n    return CosmosClient(COSMOS_DB_ENDPOINT, credential=COSMOS_DB_KEY)\n\n\nasync def initialize_database():\n    async with await get_cosmos_client() as client:\n        database = await client.create_database_if_not_exists(id=DATABASE_NAME)\n        partition_key = PartitionKey(path=\"/userId\")\n        await database.create_container_if_not_exists(\n            id=CONTAINER_NAME, partition_key=partition_key\n        )\n\n\nasync def add_conversation_turn(user_id: str, role: str, content: str):\n    async with await get_cosmos_client() as client:\n        database = client.get_database_client(DATABASE_NAME)\n        container = database.get_container_client(CONTAINER_NAME)\n        item = {\"userId\": user_id, \"role\": role, \"content\": content}\n        await container.create_item(body=item)\n\n\nasync def get_user_history(user_id: str):\n    async with await get_cosmos_client() as client:\n        database = client.get_database_client(DATABASE_NAME)\n        container = database.get_container_client(CONTAINER_NAME)\n        query = f\"SELECT * FROM c WHERE c.userId = '{user_id}'\"\n        items = [item async for item in container.query_items(query=query)]\n        return items\n\n\nasync def delete_user_history(user_id: str):\n    async with await get_cosmos_client() as client:\n        database = client.get_database_client(DATABASE_NAME)\n        container = database.get_container_client(CONTAINER_NAME)\n        items = await get_user_history(user_id)\n        for item in items:\n            await container.delete_item(item=item, partition_key=user_id)\n\n\nasyncio.run(initialize_database())","outputs":[],"execution_count":null,"metadata":{}}],"metadata":{"colab":{"from_bard":true},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}